<script type="text/javascript">
  jQuery(function() {
      // Executes a callback detecting changes with a frequency of 1 second
      jQuery("#directorioexterno_id").observe_field(1, function( ) {
        <?php echo jq_remote_function(array(
          'update'  => 'itemsdata',
          'url'     => $base_path.'/comun.php/directorio_externo/dataSearch',
          'with'    => "'idselected=' + this.value",
        )) ?>
      });      
      // Executes a callback detecting changes with a frequency of 1 second
      jQuery("#directoriodestinos_id").observe_field(1, function( ) {
        <?php echo jq_remote_function(array(
          'update'  => 'itemsdata',
          'url'     => $base_path.'/comun.php/directorio_externo/dataExtended',
          'with'    => "'idselected=' + this.value",
        )) ?>
      });
      // Executes a callback detecting changes with a frequency of 1 second
      jQuery("#unidaddocumental_id").observe_field(1, function( ) {
        <?php echo jq_remote_function(array(
          'update'  => 'tipodocumental_id',
          'url'     => $base_path.'/archivo.php/unidad_documental/loadTipoDoc',
          'with'    => "'expediente_id=' + this.value",
          'loading' => 'jQuery("#tipodocumental_id").val("").trigger("change");',
          'complete' => 'jQuery("#'.md5('Expediente.lbgettipodocumental').'").show()'
        )) ?>
      });
  });  

  Dropzone.autoDiscover = false;
  jQuery(document).ready(function() {
      Dropzone.options.myAwesomeDropzone = false;
      var myDropzone = new Dropzone("div#myDrop", { 
          url: "<?php echo url_for('com_enviada/dzFileUpload') ?>",
          // The configuration we've talked about above
          autoProcessQueue: true,       
          //uploadMultiple: true,
          addRemoveLinks: true,
          //thumbnailWidth: 50,
          //thumbnailHeight: 50,
          parallelUploads: 100,
          maxFiles: 100,
          timeout: 0,
		  maxFilesize: <?php echo (int)ini_get('upload_max_filesize'); ?>,
          dictResponseError: "Ha ocurrido un error en el server",
          acceptedFiles: 'image/*,.jpeg,.jpg,.png,.gif,.JPEG,.JPG,.PNG,.GIF,.TIF,.TIFF,.tif,.tiff,.zip,.7z,.rar,application/pdf,.psd,.csv,.xls,.doc,.dat,.ppt,.eml,.msg,.mso,.xlsx,.docx,.pptx,.txt,.3gp,.mp3,.avi,.dwg,.kmz,.kmz,.wmv,.wav,.mp4,.m4v,.mov,.mpg,.mpeg,.mpeg-4,.avc,.acc_lc,.acc,.mpc-hc,.mpc,.mid,.midi,.gdb,.asf,.aac,.ogg',
          init: function () {
              this.on("success", function (file, response) {
                  jQuery(file.previewElement).find('[data-dz-name]').html(response.name);
                  var active_value = jQuery('#ruta').val().trim() != "" ? jQuery('#ruta').val() + "," + response.name : response.name;
                  jQuery('#ruta').val(active_value);
              });
              
              this.on("removedfile", function(file) {
                  if(file != null)
                  {                    
                      var active_new = [];
                      var active_files = jQuery('#ruta').val().split(",");
                      var index = 0;
                      for(i=0; i < active_files.length; i++){
                          if(file.name != active_files[i]){
                              active_new.push(active_files[i]);
                          }
                          index++;
                      }
                      jQuery('#ruta').val(active_new.join(","));
                  }
              });
          }
      });

      //Add existing files into dropzone    
      var existingFiles = <?php echo $json_files; ?>;    
      for (i = 0; i < existingFiles.length; i++) {
          myDropzone.emit("addedfile", existingFiles[i]);
          //myDropzone.emit("thumbnail", existingFiles[i], "/image/url");
          myDropzone.emit("complete", existingFiles[i]);                
      }
  });
</script>